import {loadWorkspace,saveWorkspace,serializeWorkspace,previewRestore} from './workspace.js';
const storageKey='forgepath-readiness-v3';
let deviceStorage=null;
try{deviceStorage=window.localStorage;}catch{}
const loadedWorkspace=loadWorkspace(deviceStorage,storageKey);
let state=loadedWorkspace.state,storageStatus=loadedWorkspace.status,storageMessage=loadedWorkspace.message;
let preserveSavedCopy=storageStatus==='recovered',memoryOnly=storageStatus==='memory',recoverableText=loadedWorkspace.recoverableText;
let restorePreview=null;
const $=s=>document.querySelector(s);let view='desk',selectedSupplierId=null,query='',filters={},actionType='',actionSupplierId=null,packet=null;
let toastTimer, intakeAnalysis=null, intakeText='';
let selectedRfqId=null, rfqRole='buyer', responseEnvelope=null, responseReviewVersion=null, exchangePreview=null;
