function toast(message){$('#toast').textContent=message+((memoryOnly||preserveSavedCopy)?' Session only: export your workspace to keep changes.':'');$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function renderStorageStatus(){
 $('#storage-label').textContent=preserveSavedCopy||memoryOnly?'Session in memory':storageStatus==='fresh'?'Saves on this device':'Saved on this device';
 const banner=$('#storage-banner');banner.hidden=!preserveSavedCopy&&!memoryOnly;
 $('#storage-heading').textContent=preserveSavedCopy?'Saved copy needs recovery':'Changes are in memory only';
 $('#storage-message').textContent=preserveSavedCopy?`${storageMessage} Current actions stay in memory until you explicitly restore or reset.`:storageMessage;
 $('#export-recovery').hidden=typeof recoverableText!=='string';
}
function persist(){
 if(preserveSavedCopy||memoryOnly){renderStorageStatus();return false;}
 const result=saveWorkspace(deviceStorage,storageKey,state);
 if(result.ok){storageStatus='saved';}else{memoryOnly=true;storageStatus='memory';storageMessage=result.message;}
 renderStorageStatus();return result.ok;
}
function resetWorkspaceSelection(){selectedSupplierId=null;selectedRfqId=null;query='';filters={};packet=null;intakeAnalysis=null;intakeText='';actionType='';actionSupplierId=null;responseEnvelope=null;responseReviewVersion=null;exchangePreview=null;rfqRole='buyer';}
function replaceWorkspace(next){state=next;resetWorkspaceSelection();preserveSavedCopy=false;const saved=persist();if(saved)recoverableText=undefined;renderStorageStatus();showView('desk');return saved;}
const fmt=at=>new Date(at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const displayRef=id=>String(id).replace('SUP-DEMO-','SUP-');
const supplierById=id=>state.suppliers.find(s=>s.id===id);
function currentSupplier(){return supplierById(selectedSupplierId)||ranked()[0].supplier;}
function ranked(){const req=activeRequirement(state);return state.suppliers.map(supplier=>({supplier,match:scoreSupplier(supplier,req)})).sort((a,b)=>Number(b.match.ready)-Number(a.match.ready)||b.match.score-a.match.score);}
function focusNode(node){if(!node)return;node.setAttribute('tabindex','-1');node.focus({preventScroll:true});node.scrollIntoView({block:'start',behavior:'instant'});}
function focusSearchResults(){focusNode($('#network-results article h3')||$('#network-results .empty h3')||$('#network-count'));}
