const dialogTriggers=new WeakMap();
function closeSavedDialog(id,focusSelector){const d=$(id);dialogTriggers.delete(d);d.close();render();focusNode($(focusSelector));}
function openDialog(id){const d=$(id);dialogTriggers.set(d,document.activeElement);d.showModal();const first=d.querySelector('[autofocus]')||d.querySelector('input:not([type=checkbox]),textarea,button');first?.focus();}
for(const d of document.querySelectorAll('dialog'))d.addEventListener('close',()=>{const trigger=dialogTriggers.get(d);if(trigger?.isConnected&&!trigger.closest('[hidden]'))trigger.focus({preventScroll:true});});
function formValues(form){return Object.fromEntries(new FormData(form));}
function fillForm(form,data){for(const [name,value] of Object.entries(data))if(form.elements[name])form.elements[name].value=value??'';}
function openOnboard(){const f=$('#onboard-form');f.reset();$('#capability-card').value='';$('#onboard-error').textContent='';intakeAnalysis=null;intakeText='';$('#intake-preview').hidden=true;$('#technical-fields').open=false;$('#intake-status').textContent='Enter these three details directly, or preview pasted text above.';openDialog('#onboard-dialog');}
function openAction(type,id){actionType=type;actionSupplierId=id;const s=supplierById(id),r=activeRequirement(state),m=scoreSupplier(s,r);const f=$('#action-form');f.reset();$('#action-error').textContent='';$('#action-title').textContent=type==='advance'?'Approve RFQ drafting':type==='hold'?'Record a hold':'Request missing evidence';$('#action-context').textContent=`${s.name} · ${r.part} · revision ${r.revision}`;f.elements.note.value=type==='followup'?`Please confirm current ${r.qualification} status and provide the latest certificate, including validity dates, scope and the ${s.site.city} site. If renewal is pending or certification has lapsed, please explain.`:type==='advance'?'Recorded checks reviewed. Confirm drawing acceptance, pricing and lead time before sending a real RFQ.':'Hold pending supplier follow-up.';$('#action-submit').textContent=type==='followup'?'Record evidence request':'Record human decision';openDialog('#action-dialog');}
