function preparePacket(id){packet=buildPacket(state,id);const approved=packet.status==='Approved for RFQ drafting';$('#packet-preview').innerHTML=`<div class="packet-summary ${approved?'':'warn'}"><b>${e(packet.status)}</b><p>${e(packet.requirement.part)} · revision ${packet.requirement.revision} · drawing ${e(packet.requirement.drawingRevision)}<br>${e(packet.supplier.name)} · ${packet.match.score}/100 · ${packet.match.blockers.length} required checks open</p><p>${packet.decision?`Decision: ${e(packet.decision.reviewer)} · ${e(fmt(packet.decision.at))} · ${e(packet.decision.state)}`:'No human approval recorded.'}</p></div><div class="packet-contents"><div><b>Requirement snapshot</b><small>Drawing revision, quantities, material and process</small></div><div><b>Supplier comparison</b><small>All required checks and capability sources</small></div><div><b>Evidence history</b><small>Dates, scope, site, reviewer and superseded records</small></div><div><b>Next steps</b><small>Open questions, follow-ups and named human decision</small></div></div><p>${e(packet.notice)}</p>`;openDialog('#packet-dialog');}
function download(content,name,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',event=>{
 const b=event.target.closest('button,[data-component]');if(!b)return;
 if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}
 if(b.dataset.rfqRole){rfqRole=b.dataset.rfqRole;renderRfqWorkflow();focusNode($('#rfq-workflow h2'));return;}
 if(b.hasAttribute('data-rfq-create')){openRfqDraft();return;}
 if(b.dataset.rfqOpen){selectedRfqId=b.dataset.rfqOpen;renderRfqWorkflow();focusNode($('#rfq-workflow .rfq-current h3'));return;}
 if(b.hasAttribute('data-rfq-respond')){openRfqResponse();return;}
 if(b.hasAttribute('data-rfq-review')){openRfqReview();return;}
 if(b.dataset.rfqPacket){try{rfqDownload(b.dataset.rfqPacket,'workflow');}catch(error){toast(error.message);}return;}
 if(b.dataset.rfqTemplate){try{rfqDownload(b.dataset.rfqTemplate,'template');}catch(error){toast(error.message);}return;}
 if(b.hasAttribute('data-rfq-example')){try{const q=activeRfq();const template=responseTemplate(state,q.id);const format=$('#rfq-import-format').value;$('#rfq-import-text').value=format==='csv'?exportResponseCsv(template):JSON.stringify(template,null,2);resetExchangePreview();$('#rfq-import-text').focus();}catch(error){$('#rfq-import-error').textContent=error.message;}return;}
 if(b.hasAttribute('data-rfq-preview')){previewRfqImport();return;}
 if(b.hasAttribute('data-rfq-import')){commitRfqImport();return;}
 if(b.dataset.view){showView(b.dataset.view);return;}
 if(b.dataset.component){selectComponent(b.dataset.component);return;}
 if(b.dataset.inspect){selectedSupplierId=b.dataset.inspect;render();$('#review-panel').scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(b.dataset.networkInspect){selectedSupplierId=b.dataset.networkInspect;showView('desk');$('#review-panel').scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(b.hasAttribute('data-open-onboard')){openOnboard();return;}
 if(b.dataset.reviewAction){openAction(b.dataset.reviewAction,b.dataset.supplier);return;}
 if(b.dataset.evidence){openEvidence(b.dataset.evidence);return;}
 if(b.dataset.packet){preparePacket(b.dataset.packet);return;}
 if(b.dataset.search){query=b.dataset.search;filters={};renderNetwork();return;}
 if(b.dataset.broaden){filters[b.dataset.broaden]='';renderNetwork();focusSearchResults();return;}
 if(b.hasAttribute('data-clear-terms')){query='';renderNetwork();focusSearchResults();return;}
});
