function previewIntake(){
 intakeText=$('#capability-card').value;intakeAnalysis=analyzeCapabilityIntake(intakeText);const {fields,evidence,warnings}=intakeAnalysis;
 const preview=$('#intake-preview');preview.hidden=false;
 preview.innerHTML=`<h3 tabindex="-1">Review extracted claims</h3><p>These are suggestions from your pasted text. Missing or ambiguous values need your review.</p>${evidence.length?`<div class="extraction-list">${evidence.map(v=>`<div><b>${e(fieldLabels[v.field]||v.field)}: ${e(Array.isArray(v.value)?v.value.join(', '):String(v.value))}</b><blockquote>“${e(v.excerpt)}”</blockquote></div>`).join('')}</div>`:'<p>No fields could be reliably extracted. Enter the profile below.</p>'}${warnings.length?`<ul class="intake-warnings">${warnings.map(w=>`<li>${e(w)}</li>`).join('')}</ul>`:''}<p>Edit and confirm the fields below before creating the profile.</p>`;
 const f=$('#onboard-form');for(const name of Object.keys(fieldLabels))if(f.elements[name])f.elements[name].value='';
 fillForm(f,fields);$('#technical-fields').open=Object.keys(fields).some(k=>!['name','city','processes'].includes(k));$('#onboard-error').textContent='';$('#intake-status').textContent='Review every suggested value. Your corrections will be recorded separately from the original text.';focusNode(preview.querySelector('h3'));
}
