async function loadBenchmarkResults(){
 const target=$('#benchmark-results');
 try{
  const response=await fetch('./validation/benchmark-results.json');if(!response.ok)throw new Error('Measurement file is unavailable.');const data=await response.json();
  if(data.kind!=='deterministic-core-benchmark'||data.unit!=='milliseconds'||!Array.isArray(data.tasks)||!Number.isInteger(data.iterations)||!Number.isInteger(data.warmups)||!data.correctness)throw new Error('Measurement format is unavailable.');
  const rows=data.tasks.map(task=>{if(typeof task.label!=='string'||typeof task.fixtureWork!=='string'||!Number.isFinite(task.core?.medianMs)||!Number.isFinite(task.core?.p95Ms)||task.core.medianMs<0||task.core.p95Ms<0)throw new Error('Measurement values are unavailable.');return `<tr><td><b>${e(task.label)}</b><small>${e(task.fixtureWork)}</small></td><td>${e(task.core.medianMs.toFixed(4))} ms</td><td>${e(task.core.p95Ms.toFixed(4))} ms</td></tr>`;}).join('');
  const c=data.correctness;
  const count=(key)=>{if(!Number.isInteger(c[key])||c[key]<0)throw new Error('Fixture counts are unavailable.');return e(c[key]);};
  target.innerHTML=`<div class="table-scroll"><table class="benchmark-table"><caption>Recorded core software latency per fixture batch</caption><thead><tr><th>Fixed fixture work</th><th>Median</th><th>p95</th></tr></thead><tbody>${rows}</tbody></table></div><p class="muted">${e(data.warmups)} warm-up runs · ${e(data.iterations)} measured runs per task · ${e(data.environment?.node||'Node runtime')} · measured ${e(data.measuredAt||data.asOf||'date not recorded')}. Setup timing is reported separately in the full report; browser interaction, network, disk and human work are excluded from these core timings.</p><div class="benchmark-checks"><b>Fixed fixture checks</b><p>${count('seedSupplierCount')} seed manufacturers × ${count('requestCount')} requests = ${count('seedSupplierRequestPairs')} supplier/request pairs. ${count('expectedReadyPairs')} expected ready pairs and ${count('expectedBlockedPairs')} expected blocked pairs; ${count('falseReadySeedPairs')} false ready and ${count('falseBlockedSeedPairs')} false blocked in this fixture set.</p><p>${count('intakeCardsChecked')} intake card checked · ${count('packetsChecked')} packets checked. Results apply to these fictional fixtures only.</p></div>`;
 }catch{
  target.innerHTML='<p class="benchmark-pending">Recorded benchmark values could not be loaded. Open the full measurement report for the saved run; no latency values are shown here.</p>';
 }
}
$('#show-validation').addEventListener('click',ev=>{ev.preventDefault();$('#validation-results').open=true;focusNode($('#validation-results h2'));});
renderStorageStatus();render();loadBenchmarkResults();
